  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Satire and Irony: Jonathan Swift$j$, $j${"readings": [{"title": "Proverbs 31 (King James Version)", "url": "/portal/bible/Proverbs/31"}], "body": "The late 1600s and 1700s in Britain are often called the Age of Reason or the Enlightenment. Writers valued logic, order and common sense, and they used wit to point out folly. One of the sharpest was Jonathan Swift, an Irish writer who served as dean of Saint Patrick's Cathedral in Dublin.\n\nSatire is writing that uses humor, exaggeration and irony to criticize human weakness or social wrongs, with the aim of reform. Irony is a contrast between what is said and what is meant. Verbal irony says one thing and means another. Hyperbole is deliberate exaggeration. Understatement says less than is true.\n\nSwift's Gulliver's Travels, published in 1726, sends a ship's surgeon to lands of tiny people, giants and talking horses. Each land holds up a mirror to the pride and quarrels of England. In A Modest Proposal, published in 1729, Swift pretends to be a calm planner who offers a shocking solution to Irish poverty. The proposal is meant to be horrifying, and its horror is the point. Swift is attacking the cold, statistical way that wealthy people talked about the poor, and the neglect of the poor by those in power.\n\nScripture calls for justice for the poor. Proverbs 31:8 says, Open thy mouth for the dumb in the cause of all such as are appointed to destruction.\n\nYour task: (1) Define satire and verbal irony. (2) Explain what Swift was criticizing in A Modest Proposal. (3) Name one issue today that a satirist might address and describe the technique you would use.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.2.2, ELA.12.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.2.2, ELA.12.R.3.1", "script": "Welcome to the Age of Reason. Listen, in the late 1600s and 1700s, British writers prized logic, order and common sense, and they used wit to point out folly. The sharpest wit of all belonged to Jonathan Swift, an Irish writer and dean of Saint Patrick's Cathedral in Dublin.\n\nNow watch this. Swift was a master of satire. Satire uses humor, exaggeration and irony to criticize human weakness or social wrongs, and the goal is reform. Irony is a gap between what is said and what is meant. Hyperbole is deliberate exaggeration.\n\nLook at Gulliver's Travels, published in 1726. A ship's surgeon visits tiny people, giants and talking horses, and each land holds a mirror up to the pride and quarrels of England.\n\nThen comes A Modest Proposal, published in 1729. Swift pretends to be a calm planner who offers a horrifying solution to poverty in Ireland. The horror is the point. He is attacking the cold way that powerful people talked about the poor, and the way the poor were neglected.\n\nScripture calls us to speak for those who cannot speak for themselves, as in Proverbs 31:8. Your task is to define satire and verbal irony, explain Swift's target, and describe a modern satire. Take the four question check. Laughter can open eyes. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Satire and Irony: Jonathan Swift$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Pope, Johnson and the Order of Language$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "Alexander Pope, a poet of the early 1700s, wrote in heroic couplets, pairs of rhymed lines in iambic pentameter. His couplets are so polished that many lines have become familiar sayings. In An Essay on Criticism, published in 1711, he wrote, To err is human, to forgive divine, and A little learning is a dangerous thing. The tight form suits his subject, which is order, good judgment and humility.\n\nSamuel Johnson, a critic, essayist and talker, took on a huge task: to compile A Dictionary of the English Language, published in 1755. Before this, English had no standard dictionary. Johnson read widely, collected thousands of quotations to show how words were used, and wrote definitions with care and sometimes with humor. His biographer James Boswell wrote The Life of Samuel Johnson, a model of biography.\n\nJohnson's work shows an Enlightenment faith in order. A dictionary, a standard spelling and clear rules help people communicate. Yet language is alive, and modern dictionaries are updated constantly.\n\nScripture also honors careful speech. Proverbs 25:11 says, A word fitly spoken is like apples of gold in pictures of silver.\n\nYour task: (1) Define heroic couplet and give an example line from Pope. (2) Explain why Johnson's Dictionary mattered. (3) Choose a word and write a clear dictionary style definition with an example sentence.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.2.1, ELA.12.V.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.2.1, ELA.12.V.1.1", "script": "Now let's meet two voices of the early eighteenth century. Listen, the first is Alexander Pope, a poet who wrote in heroic couplets. That is a pair of rhymed lines in iambic pentameter. His couplets are so polished that we still quote them. In An Essay on Criticism, published in 1711, he wrote, To err is human, to forgive divine. And, A little learning is a dangerous thing.\n\nNow watch this. The second is Samuel Johnson, a critic and essayist who took on a giant task. He compiled A Dictionary of the English Language, published in 1755. Before that, English had no standard dictionary. Johnson read widely, collected thousands of quotations to show how words were used, and wrote definitions with care, and sometimes with humor.\n\nHis friend James Boswell wrote his life story, called The Life of Samuel Johnson, which is still a model of biography.\n\nLook at what this tells us. The age believed in order. A dictionary and clear rules help people communicate. Yet language is alive, and modern dictionaries change every year.\n\nScripture honors careful speech too. Proverbs 25:11, a word fitly spoken is like apples of gold in pictures of silver. Your task is to define heroic couplet, explain why the Dictionary mattered, and write a definition of your own. Take the four question check. Choose your words well. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Pope, Johnson and the Order of Language$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 John Bunyan and The Pilgrim's Progress$j$, $j${"readings": [{"title": "Hebrews 11 (King James Version)", "url": "/portal/bible/Hebrews/11"}], "body": "John Bunyan was a tinker, a mender of pots and pans, and a Baptist preacher in England. He was jailed in Bedford for preaching without a license, and during his imprisonment he began writing The Pilgrim's Progress, published in 1678. The book has been translated into more than two hundred languages and has been read in more homes than almost any book except the Bible.\n\nIt is a Christian allegory in the form of a dream. A man named Christian carries a heavy burden on his back, which stands for his sin. He leaves the City of Destruction and travels toward the Celestial City. On the way he meets Evangelist, falls into the Slough of Despond, passes through Vanity Fair, where everything is for sale, and is held captive by Giant Despair at Doubting Castle. His burden falls away at the cross.\n\nIn an allegory every person and place has a second meaning. Evangelist stands for a preacher of the gospel, Faithful and Hopeful for companions in faith, and Vanity Fair for the world's love of show and pleasure.\n\nThe story echoes Hebrews 11:13, which says that believers confessed that they were strangers and pilgrims on the earth, and Philippians 3:14, I press toward the mark for the prize of the high calling of God in Christ Jesus.\n\nYour task: (1) Explain how Bunyan wrote the book. (2) Match four places or characters with what they stand for. (3) Connect the journey to Hebrews 11:13 or Philippians 3:14.\n\nFlorida standards: ELA.12.R.1.2, ELA.12.R.1.3, ELA.12.R.1.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.2, ELA.12.R.1.3, ELA.12.R.1.4", "script": "Welcome back. Listen, I want you to meet a tinker. John Bunyan mended pots and pans, and he was also a preacher. He was jailed in Bedford for preaching without a license, and in prison he began to write one of the most loved books in English, The Pilgrim's Progress, published in 1678.\n\nNow watch this. It is an allegory in the form of a dream. A man named Christian carries a heavy burden on his back. That burden is his sin. He leaves the City of Destruction and journeys toward the Celestial City.\n\nOn the way he falls into the Slough of Despond, which is discouragement. He passes through Vanity Fair, where everything is for sale, and the world loves show and pleasure. He is captured by Giant Despair at Doubting Castle. And at the cross his burden falls away.\n\nLook at the pattern. Just as in Everyman, every person and place has a second meaning. Evangelist is a preacher of the gospel. Faithful and Hopeful are companions on the road.\n\nHebrews 11:13 says that believers confessed they were strangers and pilgrims on the earth. And Paul wrote in Philippians 3:14, I press toward the mark for the prize of the high calling of God in Christ Jesus.\n\nYour task is to explain how Bunyan wrote the book, match four places or characters to their meanings, and connect to Scripture. Take the four question check. Keep walking. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 John Bunyan and The Pilgrim's Progress$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Reading Arguments: Claims, Reasoning and Fallacies$j$, $j${"readings": [{"title": "Acts 17 (King James Version)", "url": "/portal/bible/Acts/17"}], "body": "The Enlightenment prized reasoned argument, and college work and adult life depend on it. A strong argument has a clear claim, supported by reasons and evidence, and answers opposing views. To judge an argument, ask whether the claim is clear, whether the evidence is relevant, accurate and enough, and whether the reasoning connects the two.\n\nA logical fallacy is an error in reasoning that makes an argument weak. Learn these common ones.\nAn ad hominem attacks the person instead of the argument.\nA straw man misstates an opponent's view so it is easy to defeat.\nA false dilemma presents only two choices when more exist.\nA bandwagon appeal says something is right because many people believe it.\nA slippery slope claims, without proof, that one step will lead to disaster.\nA hasty generalization draws a broad conclusion from too few examples.\n\nNotice that Scripture models careful reasoning too. In Acts 17:11, the people of Berea searched the scriptures daily, whether those things were so. They tested the claim against evidence. And 1 Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nWhen you read editorials and speeches, annotate the claim, mark the reasons, and circle any fallacy.\n\nYour task: (1) Define three fallacies in your own words. (2) Write one short example sentence for each. (3) Explain why testing a claim, as the Bereans did, is a mark of wisdom.\n\nFlorida standards: ELA.12.R.2.4, ELA.12.R.2.1, ELA.K12.EE.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.2.4, ELA.12.R.2.1, ELA.K12.EE.3.1", "script": "Now we sharpen a skill you will use in college and for the rest of your life, judging arguments. Listen, the Enlightenment prized reasoned argument, and so does every good classroom and workplace.\n\nA strong argument has a clear claim, supported by reasons and evidence, and it answers opposing views. To judge one, ask if the claim is clear, if the evidence is relevant, accurate and enough, and if the reasoning connects them.\n\nNow watch this. A logical fallacy is an error in reasoning. An ad hominem attacks the person instead of the argument. A straw man misstates an opponent's view so it is easy to knock down. A false dilemma offers only two choices when more exist. A bandwagon says it is right because many people believe it. A slippery slope says one step will lead to disaster, with no proof. A hasty generalization draws a big conclusion from too few examples.\n\nLook at the Bereans in Acts 17:11. They searched the scriptures daily, whether those things were so. They tested the claim. And 1 Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nYour task is to define three fallacies, write an example of each, and explain why testing claims is wise. Take the four question check. Think before you follow. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Reading Arguments: Claims, Reasoning and Fallacies$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Reason, Satire and the Pilgrim Journey$j$, $j${"prompt": "Write a report of at least 300 words on Enlightenment and seventeenth century prose and poetry. Use complete sentences and label each part. Proverbs 18:15 says, The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge.\n\nPart 1: Define satire and irony and explain what Swift was criticizing in A Modest Proposal.\nPart 2: Explain heroic couplets with a line from Pope, and explain why Johnson's Dictionary mattered.\nPart 3: Explain how The Pilgrim's Progress is an allegory, with four examples of what its characters or places stand for.\nPart 4: Read this original claim and name two fallacies you can find in it: Everyone knows that school uniforms are good, so anyone who disagrees must be foolish. Either we require uniforms or the school will fall into chaos.\nPart 5: Connect one idea from this unit to a passage of Scripture.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Reason, Satire and the Pilgrim Journey$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Wit, Pilgrims and Honest Reasoning$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells whether satire is an effective way to bring about change and why, (2) describes a time you saw a weak argument or a logical fallacy in real life, such as in an advertisement or a debate, (3) tells what you can learn about perseverance from Christian in The Pilgrim's Progress, and (4) connects your answer to 1 Thessalonians 5:21, which says, Prove all things; hold fast that which is good. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can we disagree with someone without attacking the person? Keep your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Wit, Pilgrims and Honest Reasoning$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Satire and Irony: Jonathan Swift$j$, $j${"questions": [{"q": "Satire is:", "options": ["Writing that uses humor and irony to criticize and reform", "A list of facts", "A prayer", "A love poem"]}, {"q": "Verbal irony is:", "options": ["Saying exactly what you mean", "Repeating a phrase", "Describing a place", "Saying one thing and meaning another"]}, {"q": "In A Modest Proposal, Swift is mainly criticizing:", "options": ["Sea travel", "Church music", "Neglect of the poor by those in power", "The weather"]}, {"q": "Gulliver's Travels was published in:", "options": ["1066", "1726", "1611", "1914"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Satire and Irony: Jonathan Swift$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,1}'::int[], array[$j$Satire aims at change through wit.$j$,$j$Irony is a contrast between statement and meaning.$j$,$j$He attacks cold indifference to poverty.$j$,$j$It was published in 1726.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Satire and Irony: Jonathan Swift$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Pope, Johnson and the Order of Language$j$, $j${"questions": [{"q": "A heroic couplet is:", "options": ["A line with no meter", "A four line stanza", "A sonnet", "Two rhymed lines of iambic pentameter"]}, {"q": "Who compiled A Dictionary of the English Language in 1755?", "options": ["Alexander Pope", "Samuel Johnson", "Geoffrey Chaucer", "William Tyndale"]}, {"q": "The line To err is human, to forgive divine comes from:", "options": ["Alexander Pope", "Milton", "Bunyan", "Jonathan Swift"]}, {"q": "James Boswell is known for writing:", "options": ["An epic", "A satire", "A biography of Samuel Johnson", "A dictionary"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Pope, Johnson and the Order of Language$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,2}'::int[], array[$j$Pope perfected the heroic couplet.$j$,$j$Johnson published his Dictionary in 1755.$j$,$j$It is from An Essay on Criticism.$j$,$j$Boswell wrote The Life of Samuel Johnson.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Pope, Johnson and the Order of Language$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: John Bunyan and The Pilgrim's Progress$j$, $j${"questions": [{"q": "John Bunyan began writing The Pilgrim's Progress while he was:", "options": ["At court", "In prison", "At a university", "On a ship"]}, {"q": "The burden Christian carries stands for:", "options": ["His books", "His money", "His sin", "His food"]}, {"q": "Vanity Fair stands for:", "options": ["A church", "The world's love of show and pleasure", "A school", "A garden"]}, {"q": "The Pilgrim's Progress is an example of:", "options": ["A satire only", "A newspaper report", "A sonnet", "An allegory"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: John Bunyan and The Pilgrim's Progress$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3}'::int[], array[$j$He was jailed in Bedford for preaching.$j$,$j$The burden is sin.$j$,$j$Everything there is for sale.$j$,$j$Characters and places carry second meanings.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: John Bunyan and The Pilgrim's Progress$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Reading Arguments: Claims, Reasoning and Fallacies$j$, $j${"questions": [{"q": "An ad hominem fallacy:", "options": ["Cites an expert", "States a claim clearly", "Attacks the person instead of the argument", "Uses strong evidence"]}, {"q": "A false dilemma:", "options": ["Uses statistics", "Tells a story", "Gives three reasons", "Offers only two choices when more exist"]}, {"q": "A hasty generalization:", "options": ["Defines terms", "Draws a broad conclusion from too few examples", "Quotes a source", "Weighs all evidence"]}, {"q": "The Bereans in Acts 17:11 are praised for:", "options": ["Arguing without reading", "Searching the scriptures to test the claims", "Leaving the city", "Ignoring the message"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Reading Arguments: Claims, Reasoning and Fallacies$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1}'::int[], array[$j$It shifts attention from the argument to the person.$j$,$j$It limits options unfairly.$j$,$j$The sample is too small.$j$,$j$They checked the claims against Scripture.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Reading Arguments: Claims, Reasoning and Fallacies$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Reason, Satire and the Pilgrim Journey$j$, $j${"questions": [{"q": "Satire is meant to:", "options": ["Confuse readers", "Criticize in order to reform", "Only entertain", "Hide the truth"]}, {"q": "Jonathan Swift wrote:", "options": ["Everyman", "Paradise Lost", "Gulliver's Travels", "Beowulf"]}, {"q": "Pope is known for:", "options": ["Sermons", "Epics in Old English", "Heroic couplets", "Plays"]}, {"q": "Johnson's Dictionary was published in:", "options": ["1066", "1755", "1914", "1611"]}, {"q": "Bunyan wrote The Pilgrim's Progress while:", "options": ["At court", "Studying at Oxford", "At sea", "Imprisoned for preaching"]}, {"q": "In The Pilgrim's Progress, Christian's burden falls away at:", "options": ["The cross", "Vanity Fair", "The city gate of Destruction", "Doubting Castle"]}, {"q": "A straw man fallacy:", "options": ["Gives strong evidence", "Misstates an opponent's view to defeat it easily", "Asks a question", "Offers a fair summary"]}, {"q": "A slippery slope fallacy claims:", "options": ["One step will lead to disaster with no proof", "Experts agree", "Two choices exist", "Evidence is strong"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Reason, Satire and the Pilgrim Journey$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,1,3,0,1,0}'::int[], array[$j$Satire aims at reform through wit.$j$,$j$Swift published Gulliver's Travels in 1726.$j$,$j$He mastered the heroic couplet.$j$,$j$The date is 1755.$j$,$j$He wrote while in Bedford jail.$j$,$j$The burden of sin falls away at the cross.$j$,$j$The weak version is easy to attack.$j$,$j$It exaggerates consequences.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Reason, Satire and the Pilgrim Journey$j$ on conflict (item_id) do nothing;
